package com.example.product.controller; import com.example.product.entity.Product; import com.example.product.repository.ProductRepository; import org.springframework.cache.annotation.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/products") @CrossOrigin(origins="http://localhost:5173") public class ProductController { private final ProductRepository repo; public ProductController(ProductRepository repo){this.repo=repo;} @GetMapping public List<Product> all(){return repo.findAll();} @GetMapping("/{id}") @Cacheable(value="products",key="#id") public Product one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping @CacheEvict(value="products",allEntries=true) public Product create(@RequestBody Product p){return repo.save(p);} }
